<?php
require 'config.php'; require_role('student'); $title='My Schedules'; $u=$_SESSION['user']; $term=selected_term($pdo); $termId=$term?(int)$term['id']:0; $current=current_term($pdo); $isCurrent=$current&&$term&&(int)$current['id']===$termId;
$q=$pdo->prepare("SELECT s.*,sub.code,sub.name,sub.units,usr.name AS faculty_name FROM schedules s JOIN subjects sub ON sub.id=s.subject_id LEFT JOIN subject_offerings o ON o.subject_id=s.subject_id AND o.day_name=s.day_name AND o.start_time=s.start_time AND o.end_time=s.end_time AND o.room=s.room LEFT JOIN users usr ON usr.id=COALESCE(o.faculty_id,sub.faculty_id) WHERE s.student_id=? AND s.term_id=? ORDER BY FIELD(s.day_name,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'),s.start_time");$q->execute([$u['id'],$termId]);$rows=$q->fetchAll();$days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];$units=array_sum(array_map(fn($r)=>(int)$r['units'],$rows));
require 'header.php';
?>
<div class="section"><div class="section-intro"><div><h2>Weekly Calendar</h2><p class="muted"><?=e($term['label']??'Academic Term')?> · Your enrolled subjects arranged by day and time.</p></div><div class="button-group"><a class="btn" href="enrollment.php">Manage Enrollment</a><a class="btn" href="enrollment_confirmation.php">Enrollment Confirmation</a></div></div>
<?php if(!$isCurrent):?><div class="info-box"><b>Previous academic term</b><p>Schedules are shown when available for this term. For completed subjects and grades, open Academic Records.</p><a href="academic_records.php?term=<?=e($term['term_key'])?>">View Academic Records →</a></div><?php endif; ?>
<div class="enrollment-overview"><div><span>Subjects</span><strong><?=e(count($rows))?></strong></div><div><span>Total Units</span><strong><?=e($units)?></strong></div><div><span>Academic Term</span><strong><?=e($term['label']??'—')?></strong></div></div>
<?php if(!$rows):?><p class="muted">No schedule records are available for this term.</p><?php else:?><div class="calendar-wrap"><div class="calendar student-timetable"><div class="cal-corner">TIME</div><?php foreach($days as $d): ?><div class="cal-day-head"><?=e(substr($d,0,3))?></div><?php endforeach; ?><?php for($h=7;$h<=18;$h++): ?><div class="cal-time"><?=date('g A',strtotime(sprintf('%02d:00:00',$h)))?></div><?php foreach($days as $day): ?><div class="cal-cell"></div><?php endforeach;?><?php endfor;?><?php $dayCols=['Monday'=>2,'Tuesday'=>3,'Wednesday'=>4,'Thursday'=>5,'Friday'=>6,'Saturday'=>7]; foreach($rows as $r): $st=strtotime($r['start_time']); $en=strtotime($r['end_time']); $startMin=((int)date('G',$st)-7)*60+(int)date('i',$st); $endMin=((int)date('G',$en)-7)*60+(int)date('i',$en); $rowStart=2+intdiv(max(0,$startMin),60); $rowEnd=2+intdiv(max(1,$endMin),60); if($endMin%60!==0){$rowEnd++;} if($rowEnd<=$rowStart){$rowEnd=$rowStart+1;} ?><div class="class-block timetable-block student-timetable-block" style="grid-column:<?=$dayCols[$r['day_name']]?>;grid-row:<?=$rowStart?> / <?=$rowEnd?>"><b><?=e($r['code'])?></b><span><?=e($r['name'])?></span><small><?=date('g:i A',$st)?>–<?=date('g:i A',$en)?></small><small><?=e($r['faculty_name']??'Assigned Faculty')?></small><small><?=e($r['room'])?></small></div><?php endforeach;?></div></div>
<div class="table-scroll"><table class="table"><tr><th>Day</th><th>Time</th><th>Subject</th><th>Teacher</th><th>Section / Room</th><th>Units</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['day_name'])?></td><td><?=date('g:i A',strtotime($r['start_time']))?> – <?=date('g:i A',strtotime($r['end_time']))?></td><td><a href="subject_details.php?id=<?=e($r['subject_id'])?>"><b><?=e($r['code'])?></b></a><br><small><?=e($r['name'])?></small></td><td><?=e($r['faculty_name']??'Assigned Faculty')?></td><td><?=e($r['section']??'—')?> / <?=e($r['room'])?></td><td><?=e($r['units'])?></td></tr><?php endforeach;?></table></div><?php endif;?></div>
<div class="admin-help"><span>Have a problem?</span><a href="contact.php">Contact Administration</a></div><?php require 'footer.php';?>
